function fact(n) {
  var f = 1;
  for (var i = 2; i <= n; i++) {
    f *= i;
  }
  return f;
}

var triangle = [];
for (var n = 0; n < 5; n++) {
  var row = [];
  for (var k = 0; k <= n; k++) {
    row.push(fact(n) / (fact(k) * fact(n - k)));
  }
  triangle.push(row);
}
console.log(triangle);

